package com.medcore.backend.api.auditoria;import jakarta.persistence.*;import java.time.*;
@Entity@Table(name="auditoria")public class Auditoria{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private String usuario;@Column(nullable=false,length=100)private String accion;@Column(nullable=false,length=100)private String entidad;@Column(name="entidad_id")private Long entidadId;@Column(length=3000)private String detalle;@Column(name="fecha_hora",nullable=false)private LocalDateTime fechaHora;@PrePersist void init(){if(fechaHora==null)fechaHora=LocalDateTime.now(ZoneId.of("America/Argentina/Buenos_Aires"));}public Long getId(){return id;}public void setId(Long v){id=v;}public String getUsuario(){return usuario;}public void setUsuario(String v){usuario=v;}public String getAccion(){return accion;}public void setAccion(String v){accion=v;}public String getEntidad(){return entidad;}public void setEntidad(String v){entidad=v;}public Long getEntidadId(){return entidadId;}public void setEntidadId(Long v){entidadId=v;}public String getDetalle(){return detalle;}public void setDetalle(String v){detalle=v;}public LocalDateTime getFechaHora(){return fechaHora;}public void setFechaHora(LocalDateTime v){fechaHora=v;}}
